	.final-sale-home-cta [data-products] {
		--shop-columns: repeat(3, minmax(0, 1fr))
	}
}

.final-sale-home-cta .product {
	--theme-text-color: rgba(255, 255, 255, 0.5);
	--theme-heading-color: #fff;
